comms.text:
@1 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְיִמְסְרִנוּן יְיָ אֱלָהָךְ בִּידָךְ וְתִשְׁבֵּי שִׁבְיְהוֹן:
@2 וְתֶחֱזֵי בְּשִׁבְיָה אִתְּתָא שַׁפִּירַת חֵזוּ וְתִתִּרְעֵי בַהּ וְתִסְבַהּ לָךְ לְאִנְתּוּ:
@3 וְתָעֵלִנַהּ לְגוֹ בֵיתָךְ וּתְגַלַח יָת רֵישַׁהּ וּתְרַבִּי יָת טוּפְרָנָהָא:
@4 וְתֶעְדֵי יָת כְּסוּת שִׁבְיַהּ מִנַהּ וְתֵיתַב בְּבֵיתָךְ וְתִבְכֵּי יָת אֲבוּהָא וְיָת אִמַהּ יְרַח יוֹמִין וּבָתַר כֵּן תֵּיעוּל לְוָתַהּ וְתִבְעֲלִנַהּ וּתְהֵי לָךְ לְאִנְתּוּ:
@5 וִיהֵי אִם לָא תִתִּרְעֵי בַהּ וְתִפְטְּרִנַהּ לְנַפְשַׁהּ וְזַבָּנָא לָא תְזַבְּנִנַהּ בְּכַסְפָּא לָא תִתָּגַר בַּהּ חֳלַף דִי עִינִיתַהּ:
@6 אֲרֵי תְהֶוְיָן לִגְבַר תַּרְתֵּין נְשִׁין חֲדָא רְחֶמְתָּא וַחֲדָא שְׂנִיאֲתָא וִילִידָן לֵהּ בְּנִין רְחֶמְתָּא וּשְׂנִיאֲתָא וִיהֵי בְּרָא בוּכְרָא לִשְׂנִיאֲתָא:
@7 וִיהֵי בְּיוֹמָא דְיַחְסֵן לִבְנוֹהִי יָת דִי יְהֵי לֵהּ לֵית לֵהּ רְשׁוּ לְבַכָּרָא יָת בַּר רְחֶמְתָּא עַל אַפֵּי בַר שְׂנִיאֲתָא בּוּכְרָא:
@8 אֲרֵי יָת בּוּכְרָא בַר שְׂנִיאֲתָא יַפְרַשׁ לְמִתַּן לֵהּ תַּרְתֵּין חָלָקִין בְּכֹל דִי יִשְׁתְּכַח לֵהּ אֲרֵי הוּא רֵישׁ תָּקְפֵּהּ לֵהּ חָזְיָא בְכֵרוּתָא:
@9 אֲרֵי יְהֵי לִגְבַר בַּר סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבַּל לְמֵימַר אֲבוּהִי וּלְמֵימַר אִמֵהּ וּמַלְפָן יָתֵהּ וְלָא יְקַבֵּל מִנְהוֹן:
@10 וְיֶחֱדוּן בֵּהּ אֲבוּהִי וְאִמֵּהּ וְיַפְּקוּן יָתֵהּ לָקֳדָם סָבֵי קַרְתֵּהּ וְלִתְרַע בֵּית דִין אַתְרֵהּ:
@11 וְיֵימְרוּן לְסָבֵי קַרְתֵּהּ בְּנָנָא דֵין סָטֵי וּמָרֵי לֵיתוֹהִי מְקַבֵּל לְמֵימְרָנָא זָלֵל בְּסָר וְסָבֵי חֲמַר:
@12 וְיִרְגְמֻנֵהּ כָּל אֶנָשֵׁי קַרְתֵּהּ בְּאַבְנַיָא וִימוּת וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ וְכָל יִשְׂרָאֵל יִשְׁמְעוּן וְיִדְחֲלוּן:
@13 וַאֲרֵי יְהֵי בִגְבַר חוֹבַת דִין דִקְטוֹל וְיִתְקְטֵל וְתִצְלוֹב יָתֵהּ עַל צְלִיבָא:
@14 לָא תְבִית נְבִלְתֵּהּ עַל צְלִיבָא אֲרֵי מִקְבַּר תִּקְבְּרִנֵהּ בְּיוֹמָא הַהוּא אֲרֵי עַל דְחָב קֳדָם יְיָ אִצְטְלַב וְלָא תְסָאֵב יָת אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@15 לָא תֶחֱזֵי יָת תּוֹרָא דְאָחוּךְ אוֹ יַת אִמְרֵהּ דְטָעָן וְתִתְכְּבֵשׁ מִנְהוֹן אָתָבָא תָתֵבִנוּן לְאָחוּךְ:
@16 וְאִם לָא קָרֵב אֲחוּךְ לְוָתָךְ וְלָא יְדַעַתְּ לֵהּ וְתַכְנְשִׁנֵהּ לְגוֹ בֵיתָךְ וִיהֵי עִמָךְ עַד דְיִתְבַּע אֲחוּךְ יָתֵהּ וְתָתֵיבִנֵהּ לֵהּ:
@17 וְכֵן תַּעְבֵּד לַחֲמָרֵהּ וְכֵן תַּעְבֵּד לִכְסוּתֵהּ וְכֵן תַּעְבֵּד לְכָל אֲבֵדַת אֲחוּךְ דִי תֵיבַד מִנֵהּ וְתַשְׁכְּחִנַהּ לֵית לָךְ רְשׁוּ לְאִתְכַּסָאָה:
@18 לָא תֶחֱזֵי יָת חֲמָרָא דְאָחוּךְ אוֹ תוֹרֵהּ רָמָן בְּאָרְחָא וְתִתְכְּבֵשׁ מִנְהוֹן אֲקָמָא תְקִים עִמֵהּ:
@19 לָא יְהֵי תִקוּן זֵין דִגְבַר עַל אִתְּתָא וְלָא יְתַקֵן גְבַר בְּתִקוּנֵי אִתְּתָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ כָּל עָבֵד אִלֵין:
@20 אֲרֵי יְעָרַע קִנָא דְצִפְּרָא קֳדָמָךְ בְּאָרְחָא בְּכָל אִילָן אוֹ עַל אַרְעָא אֶפְרוֹחִין אוֹ בֵיעִין וְאִמָא רְבֵעָא עַל אֶפְרֹחִין אוֹ עַל בֵּיעִין לָא תִסַב אִמָא עַל בְּנַיָא:
@21 שַׁלָחָא תְשַׁלַח יָת אִמָא וְיָת בְּנַיָא תִּסַב לָךְ בְּדִיל דְיֵיטַב לָךְ וְתוֹרִיפךְ יוֹמִין:
@22 אֲרֵי תִבְנֵי בֵּיתָא חַדְתָּא וְתַעְבֵּד תְּיָקָא לְאִגְרָךְ וְלָא תְשַׁוִי חוֹבַת דִין דִקְטוֹל בְּבֵיתָךְ אֲרֵי יִפֵּל דְנָפֵל מִנֵהּ:
@23 לָא תִזְרַע כַּרְמָךְ עֵרוּבִין דִילְמָא תִסְתָּאַב דִמְעַת זַרְעָא דִי תִזְרַע וַעֲלָלַת כַּרְמָא:
@24 לָא תִרְדֵי בְתוֹרָא וּבַחֲמָרָא כַּחֲדָא:
@25 לָא תִלְבַּשּׁ שַׁעַטְנֵזָא עֲמַר וְכִתָּן מְחֻבַּר כַּחֲדָא:
@26 כְּרֻסְפְּדִין תַּעְבֶּד לָךְ עַל אַרְבַּע כַּנְפֵי כְסוּתָךְ דִי תְכַסֵי בַהּ:
@27 אֲרֵי יִסַב גְבַר אִתְּתָא וְיֵעוּל לְוָתַהּ וְיִסְנִנַהּ:
@28 וִישַׁוִי לַהּ תַּסְקוֹפֵי מִלִין וְיַפֵּק עֲלַהּ שׁוּם בִּישׁ וְיֵימַר יָת אִתְּתָא הָדָא נְסֵבִית וְעַלִית לְוָתַהּ וְלָא אַשְׁכָּחִית לַהּ בְּתוּלִין:
@29 וְיִסַב אֲבוּהָא (נ''א אֲבוּהִי) דְעוּלֶמְתָּא וְאִמַהּ וְיַפְּקוּן יָת בְּתוּלֵי עוּלֶמְתָּא לָקֳדָם סָבֵי קַרְתָּא לִתְרַע בֵּית דִין אַתְרָא:
@30 וְיֵימַר אֲבוּהָא דְעוּלֶמְתָּא לְסָבַיָא יָת בְּרַתִּי יְהָבִית לְגַבְרָא הָדֵין לְאִנְתּוּ וּסְנִנַהּ:
@31 וְהָא הוּא שַׁוִי תַּסְקוֹפֵי מִלִין לְמֵימַר לָא אַשְׁכָּחִית לִבְרַתָּךְ בְּתוּלִין וְאִלֵין בְּתוּלֵי בְרַתִּי וְיִפְרְסוּן שׁוֹשִׁיפָא קֳדָם סָבֵי קַרְתָּא:
@32 וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא יָת גַבְרָא וְיַלְקוּן יָתֵהּ:
@33 וְיִגְבּוּן מִנֵהּ מְאָה סִלְעִין דִכְסָף וְיִתְּנוּן לַאֲבוּהָא דְעוּלֶמְתָּא אֲרֵי אַפֵּק שׁוּם בִּישׁ עַל בְּתוּלְתָּא דְיִשְׂרָאֵל וְלֵהּ תְּהֵי לְאִנְתּוּ לֵית לֵהּ רְשׁוּ לְמִפְטְּרַהּ כָּל יוֹמוֹהִי:
@34 וְאִם קֻשְׁטָא הֲוָה פִּתְגָמָא הָדֵין לָא אִשְׁתְּכָחוּ בְתוּלִין לְעוּלֶמְתָּא:
@35 וְיַפְּקוּן יָת עוּלֶמְתָּא לִתְרַע בֵּית אָבוּהָא וְיִרְגְמֻנַהּ אֱנָשֵׁי קַרְתַּהּ בְּאַבְנַיָא וּתְמוּת אֲרֵי עָבְדַת קְלָנָא בְּיִשְׂרָאֵל לְזַנָאָה בֵּית אֲבוּהָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@36 אֲרֵי יִשְׁתְּכַח גְבַר דְשָׁכֵב עִם אִתְּתָא אִתַּת גְבַר וְיִתְקַטְלוּן אַף תַּרְוֵיהוֹן גַבְרָא דְשָׁכֵב עִם אִתְּתָא וְאִתְּתָא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@37 אֲרֵי תְהֵי עוּלֶמְתָּא בְתֻלְתָּא דִמְאָרְסָא לִגְבַר וְיַשְׁכְּחִנַהּ גְבַר בְּקַרְתָּא וְיִשְׁכּוּב עִמַהּ:
@38 וְתַפְּקוּן יָת תַּרְוֵיהוֹן לִתְרַע קַרְתָּא הַהִיא וְתִרְגְמוּן יָתְהוֹן בְּאַבְנַיָא וִימוּתוּן יָת עוּלֶמְתָּא עַל עֵסַק דִי לָא צְוָחַת בְּקַרְתָּא וְיָת גַבְרָא עַל עֵסַק דְעַנִי יָת אִתַּת חַבְרֵהּ וּתְפַלֵי עָבֵד דְבִּישׁ מִבֵּינָךְ:
@39 וְאִם בְּחַקְלָא יַשְׁכַּח גְבַר יָת עוּלֶמְתָּא דִמְאָרְסָא וְיִתְקֶף בַּהּ גַבְרָא וְיִשְׁכּוּב עִמַהּ וְיִתְקְטֵּל גַבְרָא דְשָׁכֵב עִמַהּ בִּלְחוֹדוֹהִי:
@40 וּלְעוּלֶמְתָּא לָא תַעְבֵּד מִדַעַם לֵית לְעוּלֶמְתָּא חוֹבַת דִין דִקְטוֹל אֲרֵי כְּמָא דִיקוּם גַבְרָא עַל חַבְרֵהּ וְיִקְטְּלִנֵהּ נְפַשׁ כֵּן פִּתְגָמָא הָדֵין:
@41 אֲרֵי בְחַקְלָא אַשְׁכְּחַהּ צְוָחַת עוּלֶמְתָּא דִמְאָרְסָא וְלֵית דְפָרִיק לַהּ:
@42 אֲרֵי יַשְׁכַּח גְבַר עוּלֶמְתָּא בְתֻלְתָּא דִי לָא מְאָרְסָא וְיֶחֱדִנַהּ וְיִשְׁכּוּב עִמַהּ וְיִשְׁתַּכְּחוּן:
@43 וְיִתֵּן גַבְרָא דְיִשְׁכֻּב עִמַהּ לַאֲבוּהָא דְעוּלֶמְתָּא חַמְשִׁין סִלְעִין דִכְסַף וְלֵהּ תְּהֵי לְאִנְתּוּ חֳלַף דִי עַנְיַהּ לֵית לֵהּ רְשׁוּ לְמִפְטְרַהּ כָּל יוֹמוֹהִי:
@44 לָא יִסַב גְבַר יָת אִתַּת אֲבוּהִי וְלָא יְגַלֵי כַּנְפָא דַאֲבוּהִי:
@45 לָא יִדְכֵּי דְפָסִיק וְדִמְחַבַּל לְמֵעַל בִּקְהָלָא דַיְיָ:
@46 לָא יִדְכֵּי מַמְזֵרָא לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לֵהּ לְמֵעַל בִּקְהָלָא דַיְיָ:
@47 לָא יִדְכּוּן עַמוֹנָאֵי וּמוֹאָבָאֵי לְמֵעַל בִּקְהָלָא דַיְיָ אַף דָרָא עֲשִׂירָאָה לָא יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָא דַיְיָ עַד עָלָם:
@48 עַל עֵסַק דִי לָא עֲרָעוּ יָתְכוֹן בְּלַחְמָא וּבְמַיָא בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם וְדִי אֲגַר עֲלָךְ יָת בִּלְעָם בַּר בְּעוֹר מִפְּתוֹר אֲרַם דִי עַל פְּרָת לְלַטָּיוּתָךְ:
@49 וְלָא אָבֵי יְיָ אֱלָהָךְ לְקַבָּלָא מִן בִּלְעָם וַהֲפַךְ יְיָ אֱלָהָךְ לָךְ יָת לְוָטִין לְבִרְכָן אֲרֵי רָחֲמָךְ יְיָ אֱלָהָךְ:
@50 לָא תִתְבַּע שְׁלָמְהוֹן וְטָבָתְהוֹן כָּל יוֹמָיךְ לְעָלָם:
@51 לָא תְרַחַק אֱדוֹמָאָה אֲרֵי אֲחוּךְ הוּא לָּא תְרַחַק מִצְרָאָה אֲרֵי דַיָר הֲוֵיתָא בְאַרְעֵהּ:
@52 בְּנִין דִי יִתְיְלִידוּ לְהוֹן דָרָא תְלִיתָאָה יִדְכֵּי לְהוֹן לְמֵעַל בִּקְהָלָה דַיְיָ:
@53 אֲרֵי תִפּוֹק מַשְׁרִיתָא עַל בַּעֲלֵי דְבָבָךְ וְתִסְתַּמַר מִכֹּל מִדַעַם בִּישׁ:
@54 אֲרֵי יְהֵי בָךְ גְבַר דִי לָא יְהֵּי דְכֵי מִקְרֵהּ לֵילְיָא וְיִפּוֹק לְמִבָּרָא לְמַשְׁרִיתָא לָא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@55 וִיהֵי לְמִפְנֵי רַמְשָׁא יַסְחֵי בְמַיָא וּכְמֵעַל שִׁמְשָׁא יֵעוּל לְגוֹ מַשְׁרִיתָא:
@56 וַאֲתַר מְתַקֵן יְהֵי לָךְ מִבָּרָא לְמַשְׁרִיתָא וְתִפּוֹק תַּמָן לְבָרָא:
@57 וְסִכְּתָא תְּהֵי לָךְ עַל זֵינָךְ וִיהֵי בְּמִיתְבָךְ לְבָרָא וְתַחְפַּר בַּהּ וּתְתוּב וּתְכַסֵי יָת מִפְּקָתָךְ:
@58 אֲרֵי יְיָ אֱלָהָךְ שְׁכִינְתֵּהּ מְהַלְכָא בְּגוֹ מַשְׁרִיתָךְ לְשֵׁזָבוּתָךְ וּלְמִמְסַר בַּעֲלֵי דְבָבָךְ קֳדָמָךְ וּתְהֵי מַשְׁרִיתָךְ קַדִישָׁא וִלָא יִתְחֲזֵי בָךְ עֲבֵרַת פִּתְגָם וִיתוּב מֵימְרֵהּ מִלְאוֹטָבָא לָךְ:
@59 לָא תִמְסַר עֶבֶד עַמְמִין לְיַד רִבּוֹנֵהּ דְיִשְׁתֵּזֵב לְוָתָךְ מִלְוָת רִבּוֹנֵהּ:
@60 עִמָךְ יִתֵּב בֵּינָךְ בְּאַתְרָא דִי יִתִּרְעֵי בַּחֲדָא מִן קִרְוָיךְ בִּדְיֵיטַּב לֵהּ לָא תוֹנִנֵהּ:
@61 לָא תְהֵי אִתְּתָא מִבְּנַת יִשְׂרָאֵל לִגְבָר עָבֵד וְלָא יִסַב גַבְרָא מִבְּנֵי יִשְׂרָאֵל אִתְּתָא אָמָא:
@62 לָא תָעֵל אֲגַר זַנִיתָא וְחוּלְפַן כַּלְבָא לְבֵית מַקְדְשָׁא דַיְיָ אֱלָהָךְ לְכָל נִדְרָא אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ אַף תַּרְוֵיהוֹן:
@63 לָא תְרַבֵּי לַאֲחוּךְ רִבִּית כְּסַף רִבִּית עִבוּר רִבִּית כָּל מִדַעַם דְמִתְרַבֵּי:
@64 לְבַר עַמְמִין תְּרַבֵּי וְלַאֲחוּךְ לָא תְרַבֵּי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל אוֹשָׁטוּת יְדָךְ עַל אַרְעָא דִי אַתְּ עָלֵל:לתַמָן לְמֵירְתַהּ:
@65 אֲרֵי תִדַר נְדַר קֳדָם יְיָ אֱלָהָךְ לָא תְאַחַר לְשַׁלָמוּתֵהּ אֲרֵי מִתְבַּע יִתְבְּעִנֵהּ יְיָ אֱלָהָךְ מִנָךְ וִיהֵי בָךְ חוֹבָא:
@66 וַאֲרֵי תִתִּמְנַע לְמִנְדַר לָא יְהֵי בָךְ חוֹבָא:
@67 אַפָּקוּת סִפְוָתָךְ תִּטַר וְתַעְבֵּד כְּמָא דִי נְדַרְתָּא קֳדָם יְיָ אֱלָהָךְ נְדַבְתָּא דִי מַלֶלְתָּא בְּפוּמָךְ:
@68 אֲרֵי תִתָּגַר בְּכַרְמָא דְחַבְרָךְ וְתֵיכוּל עִנְבִין כְּנַפְשָׁךְ שִׂבְעָךְ וּלְמָאנָךְ לָא תִתֵּן:
@69 אֲרֵי תִתָּגַר בְּקַמְתָא דְחַבְרָךְ וְתִקְטוֹף מְלִילָן בִּידָךְ וּמַגְלָא לָא תְרִים עַל קַמְתָא דְחַבְרָךְ:
@70 אֲרֵי יִסַב גְבַר אִתְּתָא וְיִבְעֲלִנַהּ וִיהֵי אִם לָא תַשְׁכַּח רַחֲמִין בְּעֵינוֹהִי אֲרֵי אַשְׁכַּח בַּהּ עֲבֵרַת פִתְגָם וְיִכְתּוֹב לַהּ גֵט פִּטוּרִין וִיהַב בִּידַהּ וְיִפְטְּרִנַהּ מִבֵּיתֵהּ:
@71 וְתִפּוֹק מִבֵּיתֵהּ וּתְהַךְ וּתְהֵי לִגְבַר אָחֳרָן:
@72 וְיִסְנִנַהּ גַבְרָא בַתְרָאָה וְיִכְתּוֹב לַהּ גֵטּ פִטּוּרִין וְיִתֵּן בִּידַהּ וְיִפְטְרִנַהּ מִבֵּיתֵהּ אוֹ אֲרֵי יְמוּת גַבְרָא בַתְרָאָה דְנָסְבַהּ לֵה לְאִנְתּוּ:
@73 לֵית לֵהּ רְשׁוּ לְבַעֲלַהּ קַדְמָאָה דִי פָטְרַהּ לְמִתֻּב לְמִסְבַהּ לְמֶהֱוֵי לֵה לְאִנְתּוּ בָּתַר דִי אִסְתָּאָבַת אֲרֵי מְרָחָקָא הִיא קֳדָם יְיָ וְלָא תְחַיַב יָת אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא:
@74 אֲרֵי יִסַב גְבַר אִתְּתָא חַדְתָּא לָא יִפּוֹק בְּחֵילָא וְלָא יֵעִבַר עֲלוֹהִי לְכָל מִדָעַם פָּנֵי יְהֵי לְבֵיתֵהּ שַׁתָּא חֲדָא וְיַחְדֵי יָת אִתְּתֵהּ דִי נְסַב:
@75 לָא יִסַב מַשְׁכּוֹנָא רֵחַיָא וְרִכְבָּא אֲרֵי בְהוֹן מִתְעֲבֵד מָזוֹן לְכָל נְפַשׁ:
@76 אֲרֵי יִשְׁתְּכַח גְבַר גָנֵב נַפְשָׁא מֵאֲחוֹהִי מִבְּנֵי יִשְׂרָאֵל וְיִתָּגַר בֵּהּ וִיזַבְּנִנֵהּ וְיִתְקְטֵל גַנָבָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@77 אִסְתַּמַר בְּמַכְתַּשׁ סְגִירוּ לְמִטַּר לַחֲדָא וּלְמֶעְבָּד כְּכֹל דִי יַלְפוּן יָתְכוֹן כָּהֲנַיָא לֵוָאֵי כְּמָא דִי פַקֶדְתִּנוּן תִּטְרוּן לְמֶעְבָּד:
@78 הֱוֵי דְכִיר יָת דִי עֲבַד יְיָ אֱלָהָךְ לְמִרְיָם בְּאָרְחָא בְּמִפָקְכוֹן מִמִצְרָיִם:
@79 אֲרֵי תַרְשֵׁי בְחַבְרָךְ רְשׁוּ מִדָעַם לָא תֵעוּל לְבֵיתֵהּ לְמִסַב מַשְׁכּוֹנֵהּ:
@80 בְּבָרָא תְּקוּם וְגַבְרָא דִי אַתְּ רָשֵׁי בֵהּ יַפֵק לְוָתָךְ יָת מַשְׁכּוֹנָא לְבָרָא:
@81 וְאִם גְבַר מִסְכֵּן הוּא לָא תִשְׁכּוּב בְּמַשְׁכּוֹנֵהּ:
@82 אָתָבָא תָתֵב לֵהּ יָת מַשְׁכּוֹנָא כְּמֵעַל שִׁמְשָׁא וְיִשְׁכּוּב בִּכְסוּתֵהּ וִיבָרֵכִנָךְ וְלָךְ תְּהֵי זְכוּתָא קֳדָם יְיָ אֱלָהָךְ:
@83 לָא תַעֲשׁוֹק אֲגִירָא עַנְיָא וּמִסְכֵּנָא מֵאַחָיךְ אוֹ מִגִיוֹרָךְ דִי בְאַרְעָךְ בְּקִרְוָיךְ:
@84 בְּיוֹמֵהּ תִּתֵּן אַגְרֵהּ וְלָא תֵעוּל עֲלוֹהִי שִׁמְשָׁא אֲרֵי עַנְיָא הוּא וְלֵהּ הוּא מְסַר יָת נַפְשֵׁהּ וְלָא יִקְרֵי עֲלָךְ קֳדָם יְיָ וִיהֵי בָךְ חוֹבָא:
@85 לָא יְמוּתוּן אֲבָהָן עַל פּוּם בְּנִין וּבְנִין לָא יְמוּתוּן עַל פּוּם אֲבָהָן אֱנַשׁ בְּחוֹבֵהּ יְמוּתוּן:
@86 לָא תַצְלֵי דִין גִיוֹרָא וְיִתַּמָא וְלָא תִסַב מַשְׁכּוֹנָא לְבוּשׁ אַרְמְלָא:
@87 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּמִצְרַיִם וּפָרְקָךְ יְיָ אֱלָהָךְ מִתַּמָן עַל כֵּן אֲנָא מְפַקְדָךְ לְמֶעְבַּד יָת פִּתְגָמָא הָדֵין:
@88 אֲרֵי תַחְצוֹד חֲצָדָךְ בְּחַקְלָךְ וְתִנְשֵׁי עֻמְרָא בְחַקְלָא לָא תְתוּב לְמִסְבֵהּ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי בְּדִיל דִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ:
@89 אֲרֵי תַחְבּוֹט זֵיתָךְ לָא תְפַלֵי בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@90 אֲרֵי תִקְטוֹף כַּרְמָךְ לָא תְעָלֵל בַּתְרָךְ לְגִיוֹרָא לְיִתַּמָא וּלְאַרְמְלָא יְהֵי:
@91 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרָיִם עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵעְבַּד יָת פִּתְגָמָא הָדֵין:
@92 אֲרֵי יְהֵי דִין בֵּין גֻבְרַיָא וְיִתְקָרְבוּן לְדִינָא וִידוּנֻנוּן וִיזַכּוּן יָת זַכָּאָה וִיחַיְבוּן יָת חַיָבָא:
@93 וִיהֵי אִם בַּר חַיָבָא לְאַלְקָאָה חַיָבָא וְיִרְמִנֵהּ דַיָנָא וְיַלְקִנֵהּ קֳדָמוֹהִי כְּמִסַת חוֹבְתֵהּ בְּמִנְיָן:
@94 אַרְבְּעִין יַלְקִנֵהּ לָא יוֹסֵף דִילְמָא יוֹסֵף לְאַלְקָיוּתֵהּ עַל אִלֵין מָחָא רַבָּא וְיֵקַל אֲחוּךְ לְעֵינָיךְ:
@95 לָא תֵחוֹד פּוּם תּוֹרָא בִּדְיָשֵׁהּ:
@96 אֲרֵי יֵתְבוּן אַחִין כַּחֲדָא וִימוּת חַד מִנְהוֹן וּבַר לֵית לֵהּ לָא תְהֵי אִתַּת מֵתָנָא לְבָרָא לִגְבַר אוֹחֲרָן יְבָמַהּ יֵעוּל עֲלַהּ וְיִסְבַהּ לֵהּ לְאִנְתּוּ וְיִבְּמַהּ:
@97 וִיהֵי בּוּכְרָא דִי תְלִיד יְקוּם עַל שְׁמָא דַאֲחוּהִי מֵתָנָא וְלָא יִתִּמְחֵי שְׁמֵהּ מִיִשְׂרָאֵל:
@98 וְאִם לָא יִצְבֵי גַבְרָא לְמִסַב יָת יְבִמְתֵּהּ וְתִסַק יְבִמְתֵהּ לִתְרַע בֵּית דִינָא לָקֳדָם סָבַיָא וְתֵימַר לָא צָבֵי יְבָמִי לַאֲקָמָא לַאֲחוּהִי שְׁמָא בְּיִשְׂרָאֵל לָא אָבֵי לְיַבָּמוּתִי:
@99 וִיקְרוּן לֵהּ סָבֵי קַרְתֵּהּ וִימַלְלוּן עִמֵהּ וִיקוּם וְיֵימַר לָא רְעֵנָא לְמִסְבַהּ:
@100 וְתִתְקְרַב יְבִמְתֵּהּ לְוָתֵה לָקֳדָם סָבַיָא וְתַשְׁרֵי סֵינֵהּ מֵעַל רַגְלֵהּ וְתֵרוֹק בְּאַנְפּוֹהִי וְתָתֵב וְתֵימַר כְּדֵין יִתְעֲבֵד לִגְבַר דִי לָא יִבְנֵי יָת בֵּיתָא דַאֲחוּהִי:
@101 וְיִתְקְרֵי שְׁמֵהּ בְּיִשְׂרָאֵל בֵּית שְׁרִי סֵינָא:
@102 אֲרֵי יִנְצוּן גֻבְרִין כַּחֲדָא גְבַר וַאֲחוּהִי וְתִתְקְרֵב אִתַּת חַד לְשֵׁזָבָא יָת בַּעֲלַהּ מִיַד מָחוּהִי וְתוֹשֵׁט יְדַהּ וְתִתְקֵף בְּבֵית בַּהֲתְּתֵהּ:
@103 וּתְקוּץ יָת יְדַהּ לָא תְחוּס עֵינָךְ:
@104 לָא יְהֵי לָךְ בְּכִיסָךְ מַתְקַל וּמַתְקָל רַבְּתָא וּזְעֶרְתָּא:
@105 לָא יְהֵי לָךְ בְּבֵיתָךְ מְכִילָא וּמְכִילָא רַבְּתָא וּזְעֶרְתָּא:
@106 מַתְקִלִין שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ מְכִילָן שָׁלְמִין דִקְשׁוֹט יְהוֹן לָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@107 אֲרֵי מְרָחָק קֳדָם יְיָ אֱלהָךְ כָּל עָבֵד אִלֵין כֹּל עָבֵד שְׁקַר:
@108 הֲוֵי דְכִיר יָת דִי עֲבַד לָךְ עֲמָלֵק בְּאָרְחָא בְּמִפָּקְכוֹן מִמִצְרָיִם:
@109 דִי עָרְעָךְ בְּאָרְחָא וְקָטֵל בָּךְ כָּל דַהֲווֹ מִתְאַחֲרִין בַּתְרָךְ וְאַתְּ מְשַׁלְהֵי וְלָאֵי וְלָא דָחֵיל מִן קֳדָם יְיָ:
@110 וִיהֵי כַּד יְנִיחַ יְיָ אֱלָהָךְ לָךְ מִכָּל בַּעֲלֵי דְבָבָךְ מִסְחוֹר סְחוֹר בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לְמֵירְתַהּ תִּמְחֵי יָת דוּכְרָנָא דַעֲמָלֵק מִתְּחוֹת שְׁמַיָא לָא תִּתִּנְשֵׁי: פפפ:

@1 **כי תצא למלחמה על אויביך וגו'**. צריך לדעת למה הוצרך לומר כל זה שלא היה צ''ל אלא כי תראה בשביה אשת וגו', עוד אחר שאמר כי תצא למלחמה לא היה צריך לומר על אויביך, ואולי כי לפי שבא הכתוב להתיר יפת תואר שאסורה שלא בשעת מלחמה, גם להתיר קדלי דחזירי (חולין י''ז.) ושאר איסורין, חש הכתוב שביציאת ישראל למלחמה רגליהם לרע ירוצו כדי שיהנו מדבר איסור, לזה בא הכתוב והתנה ואמר **כי תצא** תהיה יציאתך למלחמה להנקם מאויביך שהם אויבי ה', על דרך אומרו (תהלים קל''ט) הלא משנאיך ה' אשנא וגו' לאויבים היו לי, לטעם זה תהיה יציאתך, ואם תעשה כן ונתנו ה' אלהיך בידך ושבית שביו, ומזה אתה למד שזולת כן אם תהיה יציאתך לטעם אחר והטעם מובן ממה שאמר בענין אינו מובטח שיתנהו ה' בידו:
@1 **ושבית שביו**. מצוה, כדי שלא יראה כמזלזל במתנת מלך, או נתכוון לאסור יפת תואר כל עוד שלא שבו שביו, שלא יאמר אדם כיון שהותרה לי אחטפנה ואוליכנה ואבעלנה, תלמוד לומר **ושבית שביו וראית בשביה** פירוש כשתשבה אותה ותהיה שלך אם ראית בשביה וגו', וטעם אומרו **שביו** ולא אמר אותו, רבותינו ז''ל אמרו (ספרי) שהכתוב מדבר במלחמת רשות, ודקדק לומר **שביו** אפילו הוא מהכנעני שנאמר בו (לעיל כ' ט''ז) לא תחיה כל נשמה:
@1 **עוד** ירצה לפי שנאמר ונתנו ה' וגו' בידך, לזה כשאמר **ושבית** גמר אומר **שביו** פירוש מה ששבוי ועומד לפניך, עוד רמז שהגם שתהיה אתה בגדר שביו לפי ערך המשתער ללוחם ונלחם אף על פי כן ושבית, ומזה עיניך תחזינה כי ה' הוא הנותנו לפניך ולא כחך ועוצם ידך עושה חיל:
@2 (יא~יד) **וראית בשביה אשת יפת תואר**. הנה מאומרו **יפת תואר** משמע דוקא יפת תואר ומאומרו **וחשקת בה** דרשו בספרי אפילו כעורה, וזה מן התימה למה יאמר יפת תואר ויצטרך לרבות כעורה היה לו לומר וראית אשת ולא יכתוב לא יפת תואר ולא וחשקת:
@2 **ולישב** הכתוב צריך להעיר בענין למה יצו ה' כדברים האלה לטמא אדם עצמו בבת אל נכר, ובפרט בעת מעשה הנס במקום שצריך להוסיף טהרה ודביקות בה' יתיר לעשות מעשה כיעור השנאוי אצלו יתברך, וזה יפעיל הרחקת דביקותנו בו יתברך, בשלמא התרת אכילת איסור מצינו לרמב''ם ז''ל (פ''ח הל' מלכים) שנתן טעם אם ירעב והוא טעם נכון, אבל מעשה זה יתעבנו עושנו, ורבותינו ז''ל אמרו (קידושין כ''א:) לא דברה תורה אלא כנגד יצר הרע, ומן הראוי הוא להכניעו ולאבדו מלב עם קדוש בזמן ההוא אשר מלכם בראשם להלחם להם:
@2 **אכן** יסוד הדבר וסודו הוא על פי דבריהם ז''ל (ז''ח בלק נ''ג) שאמרו שבחטא אדם הראשון נשבו כמה נשמות יקרות ביד סטרא אחרא והם נשמות הגרים, וצא ולמד כמה וכמה גדולי עולם באים מהאומות ורות המואביה תוכיח וכמה גדולי עולם שמעיה ואבטליון ואונקלוס הגר וכאלה רבות:
@2 **עוד** אגלה לך סוד אחד תמצא נשמה טהורה דבוקה בנשמה טמאה ואין כח בטהורה להטות הטמאה להטיב והיא מונחת שם עד עת דרור, וצא ולמד כיוצא בזה מנשמת ר' חנינא בן תרדיון שהיתה דבוקה בשכם בן חמור כרמוז בתיבת רחב''ת ידים (בראשית ל''ד) כאמור בדברי המקובלים (ליקוטי תודה וישלח) ומצינו שהנפש הלזו לא עשתה מפעל טוב בשכם ויצתה כשדבק בדינה מצאה הנפש מינה ונדבקה בו כאומרו (שם) ותדבק נפשו בדינה, ושמור לך כלל זה, ויש נפש קדושה בין הקליפה שבמקום שכונתה תטה לב השוכנת בתוכו להטיב ויגרשו חלק הרע או ימתקוהו, והם הגרים המתגיירים מן האומות מעצמן כרות המואביה וכנעמה, וכמו שראינו בעינינו גרים שמעצמם באים ומתגיירים:
@2 **והנה** כבר כתבתי כמה פעמים כי באמצעות מעשה המצוה יתלבש באדם אור השכינה ויגרש ממנו חלק הרע כאומרו (קהלת ח') שומר מצוה לא ידע דבר רע, ובפרט שלוחי מצוה ועיין מה שפירשתי בפרשת שלח לך ששלוחי מצוה בשעת שליחותם אפילו מיצר הרע מצותם מצילתם, וכמו כן העוסק בעבירה מתלבשת בו רוח הטומאה ומעותת דרכו:
@2 **ואחרי** הודיע ה' אותנו את כל זאת יאירו מאמרי אל עליון כשמש בצהרים במצוה זו, והוא לפי שהקדים **כי תצא למלחמה** וגו' שיציאתו היא לדבר מצוה כמו שפירשנו למעלה, אמר עוד אם ראה בשביה פירוש בשעת שביה, וכמו שכן דקדק רמב''ם בפ''ח מה' מלכים כי באותה שעה עודנו עוסק במצוה, אם יראה אשת יפת תואר פירוש אשת סמוך, ורבותינו ז''ל אמרו (קידושין כ''א:) אשת איש, ודבריהם אמת אלא שאם לדבריהם לכד יכוין היה לו לומר אשת איש לא אשת יפ''ת, אלא באה להעיר שבאמצעות היותו עוסק במצוה יגלה ה' את עיניו להכיר בגויה שיש בה יפת תואר שהיא נשמה הקדושה הנקראת יפת תואר, כי זוהר נשמות הקדושות מופלא ועצום הוא, וזאת האשה קנתה בה חלק זה הטוב, ולזה קראה הכתוב אשת יפת תואר והכרתה הוא על ידי שאתה רואה שאתה חושק בה בזמן שאתה דבוק בשכינה באמצעות היותך עסוק בשליחות מצוה כאמור זה יעירך שלדבר טוב חשקת:
@2 **ודקדק** לומר **בה** ולא אמר אותה, להעיר כי לא לאשה אתה חושק אלא למה שבה שהיא יפת תואר שהוא חלק הטוב הדומה לנפש הטהורה וכפי זה הגם שכעורה האשה בכלל ההיתר כי אינו חוזר יפ''ת לגולם הנגלה כי אליו לא ימשך תאות ישראל במצב זה כמו שאמרנו, ואמר **ולקחת לך לאשה**, הנה בכל מאמר המתכנה לה אמר הכתוב בלשון כינוי והבאתה וגו' ובעלתה וגו' ושלחתה וכאן אמר **ולקחת**, שינה הכתוב להעירך שהלקיחה היא בנעלם שהיא נפש הקדושה שבאמצעות הענין יהיה לו בה לקיחה אחרת שיזכה ביפת תואר, כי כשידבק איש ישראל באשה שבה חלק מהטוב תכף יקנה מקומו חלק הטוב בישראל ויזכה בו כמו שזכתה דינה בת יעקב בנפש קדושה בפגוע בה שכם בן חמור:
@2 **והנה** לפי שיש ב' בחינות בדביקות הקדושה בקליפה כמו שזכרנו למעלה, וזאת האשה אין ידוע אם חלק הדבוק בה הוא דבר היוצא בדביקה ראשונה כנזכד ונשארה האשה חלוטה בחלק הרע ונתרוקנה מחלק הטוכ, או אפשר שכולה נחלטת בחלק הטוב כרות וכנעמה, לזה יצו ה' **והבאתה אל תו** ך **ביתך** וגו' וירחיק ממנו חלק דביקות בחינת הרע, ואז תבדק האשה אחר שלשים יום אם נתגיירה אשתו זו והרי היא כרות וכנעמה, והוא אומרו **והיתה לך לאשה** אם יחפוץ, ואם לא יחפוץ וגו' זה לך האות כי חלק הטוב שהיה בה יצא על ידי מעשה הראשון ונחלק הרע, ולצד שיש מקום שיתאוה האדם לאשה נכריה בדרך זנות, כי לא אמרנו שלא יתאוה לנכרית אלא אם יש בה נפש קדושה דוקא בזמן שהוא בדבר מצוה כמו שכתבנו, מה שאין כן אחרי כן, לזה צוה ה' **וגלחה את ראשה ועשתה את צפרניה** וגו' וכל הדברים המנוולים את האשה להסיר תאוה הטבעית, ואם נתגיירה וחפץ בה זה לך האות כי נתמתקה ונחלט ממנה חלק הרע ולזה והיתה לו לאשה, ואם לא יחפוץ בה, דקדק לומר **בה** להעיר כי החפץ הוא במה שבה שהוא חלק הטוב:
@2 **ואומרו ושלחתה לנפשה**. דקדק לומר **לנפשה**, לתת טעם למה ישלחנה ולא ימכרנה ויהנה מדמיה כיון שהיא מכלל השביה שנתן לו ה', ואמר הטעם הוא לנפשה פירוש בשביל נפשה שהיא יפת תואר שרמז בתחילה אחר שנהנה ממנה, או על זה הדרך **לנפשה** פירוש הטמאה של הגויה לשלול כי נפש יפ''ת הטהורה כבר זכית בה ולא נשאר בה אלא נפש הגויה, ואומרו **ומכור לא תמכרנה** כי ה' חפץ שלא ינהגו ישראל עם בחינת הרע בדרך זה, על דרך אומרו (תהלים ס''ט) אשר הכית רדפו שרוח הקודש מתרעמת על האומות שאחר שרואים ישראל מוכים רודפים אותם, וזו כיוצא בה שאחר שהוציא בולעה מפיה לא יהנה עוד מכספה:
@2 **וגמר** אומר תחת **אשר עניתה** פירוש אשר הוצאת ממנה עושרה וטובה שהיא יפת תואר ועשית אותה עניה עשית אותה מעונה עשית אותה עכורה, וזה יעיד עוד על דברינו, כי היתכן בעולם שישראל הבא על אשה הגויה הוא מענה אותה והלא אמרו ז''ל (ע''ז כ''ב:) חביבה עליהם בהמתן של ישראל יותר מנשותיהן ונשותיהם יותר מהם, ומה עינוי הוא זה לגויה, אלא הכוונה הוא עינוי הנעלם שהוא שלל קדש ממנה:
@2 **ובדרך** רמז תתבאר הפרשה על זה הדרך הנה כל בנין העולם וקיומו תלוי במעשה עם בני ישראל אם יטיבו דרכיהם העולם קיים וישמחו השמים ותגל הארץ, גם ה' אלהינו ישמח ויגל בנו, ויושר דרכם של ישראל תלוי בנצחון יצר הרע ובא הכתוב להעיר האדם כי ביציאתו מעולם העליון לבא לעולם הזה יהיה מוכן למלחמה, כי לא יחשוב שאין צריך תגבורת לנצחון זה אלא אדרבה לזו יקרא מלחמה על דרך אומרם (אבות פ''ד) איזהו גבור הכובש את יצרו שאין גבורה גדולה מזו, ולזה אמר **למלחמה** בפת''ח תחת הלמ''ד:
@2 **ואומרו על אויביך**, בא להעיר כי לא מלחמה זו כגבור הלוחם ללכוד עיר וכשיקוץ במלחמה יפנה וילך לעצמו אלא כאדם הלוחם עם אויבו שאם יתרשל יקום עליו והכהו, כמו כן אם יתרשל האדם מללחום את האויב יקום עליו ויאבדהו מן העולם, ומבטיחו הכתוב שהגם שתקיף הוא היצר מכח האנושי אף על פי כן יתנהו ה' בידו, ואומר **ושבית שביו** דקדק לומרו שביו ולא אותו, שאין בו ממש בעצמו והעדרו הוא המקווה אלא שביו פירוש מה ששבה הוא מבחינת הטוב ממך ומכיוצא בך בפיתויו ובנצחונו שכמה נשמות מעם בני ישראל שבויות ביד ו:
@2 **ואומרו** וראית בשביה **אשת יפת תואר**. אמר אשת סמוך פירוש נשמת אדם, כי אין הס''מ שולט בנפש עד שתרד מטה ותכנס באדם ממנו הוא לוקחה בשבי, והנפש תקרא אשה, וקרא לזו יפת תואר כי הנפש יפה עד מאד אלא שמתנוולת במעשיה הרעים וכשינוצח היצר אז ישכיל האדם בנפשו מה יפה ומה נעימה היא:
@2 **ואמר וחשקת בה** פירוש אז החשק שהיה לו בדברי היצר ובפיתויו ילבישם בה לתקן לה המושכלות ועולם הקיים שכולו טוב, ואומרו **והבאתה אל תוך ביתך** לפי שעל ידי פיתוי הרע מתרחקת הנפש מהגוף ושוכן חלק רע במקומה, כדרך אומרו (איוב י''ח) טורף נפשו באפו, והגוף יקרא בית על דרך אומרם (תענית י''א.) מי מעיד באדם קורות ביתו שהוא הגוף, וכשנוצח יצרו יביא נפשו לתוך ביתו ויקרא בעל נפש, ולהיות שהנפש שקנה ממקום טמא צריך לנקותה מתחלואי הרע הנדבק בה שהוא בחינת שער הראש, והוא אומרו **וגלחה את ראשה**, גם בחינת הקליפה הרמוזה בצפרנים אמר כנגדה **ועשתה את צפרניה** לשון תיקון, ותסיר מסוה הטומאה המתכסה בה הנפש מרוח הטומאה, והוא אומרו **והסירה את שמלת שביה מעליה** פירוש שקנתה משביתה במקום טמא, וזה יהיה על ידי מירוק החטאים ודרכי התשובה והכנת הדעת מול אלהי ישראל ב''ה, ויבחר מקום מושב לה בית מיוחד לישראל שהוא בית המדרש, והוא אומרו **וישבה בביתך**, ותתודה בבכי על אשר מעלה באביה ואמה ועל פרידתה מהם, אביה זה הקב''ה, אמה היא כנ''י (ברכות ל''ה), ירח ימים זה שיעור המספיק לשב, או ירמוז לחודש המיוחד לתשובה שהוא חודש אלול:
@2 **ואחר כז תבוא אליה**. פירוש אתה תכנס ליהנות מאורה בסוד אומרו נפש עמל עמלה לו, ותסייעהו לעמוד בדרך הנאות, ותקרא אתה בעליה שקנית אותה בכח מעשיך והוא אומרו **ובעלתה**, גם ליום התחיה תהיה מיוחדת לך לחזור לגופך ותעמוד בה, והוא אומרו **והיתה לך לאשה**, וחזר הכתוב לצוות על הנפש שאם האיש לא נטה לבו לקוות להטיב לנפשו ולהתעצם להאיר לה בעולם העליון, על כל פנים יזהר שלא יריע לה כדרך שאמר שלמה (קהלת י''ב) והרוח תשוב אל האלהים אשר נתנה, ודרשו במס' שבת (קנ''ב:) תנה לו כמו שנתנה לך, והוא אומרו **אם לא חפצת בה ושלחתה לנפשה** פירוש שלא תמסרנה ביד שבאי אלא בת חורין ואין עליה יד מושל:
@2 **או** ירצה על דרך מה שאמרו בזוהר (ח''ג ס''ז) בפסוק נפשי אויתיך בלילה שעל השכינה הוא אומר נפשי, והוא מה שרמז באומרו **ושלחתה לנפשה** שהוא השכינה שתחזור למקום שיצתה ממנו, ואומרו **ומכור לא תמכרנה** וגו' על דרך מה שדרשו בספר הזוהר (ח''ב צ''ז) בפ' לעם נכרי לא ימשול למכרה, ואומרו **בכסף** לפי שיאמר אדם איך ימשול אדם בנפשו למוכרה לזה אמר בכסף לשון כוסף, כי באמצעות תאות וכוסף לבות בני אדם ימכרו את נפשם ביד אויב, ורמזנו מזה בפסוק (ויקרא כ''ח ל''ז) את כספך לא תתן לו בנשך וגו', ואומרו **לא תתעמר** כמו שתרגם אונקלום לא תתגר פירוש לא תגרה בה מחבלים המתגרים בנפש החוטאת, תחת אשר עניתה כי החטא יקרא בערך הנפש עינוי:
@6 **והיה הבן הבכור וגו'**. אמר הכתוב בדרך ודאית, על דרך אומרו (בראשית כ''ט) וירא ה' כי שנואה לאה, כי ה' יראה בנשברי לב לסומכם:
@7 **הנחילו את בניו את אשר וגו'**. ולא אמר ביום הנחילו את אשר יהיה לו את בניו, להסמיך תיבת הנחילו למאמר את בניו, לרמוז סברת חכמים שאמרו (ב''ב ק''ל.) שיכול האב להנחיל לבן אחד מבניו יותר ממה שנוגע לו כפי החלוקה:
@7 **לא יוכל לבכר וגו'**. ואם ביכר עובר בלאו, ובזה יתיישב מה שהקשו התוספות שם בדיבור המתחיל תלמוד לומר לסברת רבנן:
@9 **כי יהיה לאיש וגו' איננו שומע**. צריך לדעת אומרו **איננו** שהיה לו לומר אינו שומע, ואולי שבא להעיר כי כשאדם ממליך בתוכו יצר הרע נשללת ממנו הידיעה והשמיעה מהנאמר אליו, כי היצר עומד על מפתח הלב ומונע הדברים מהגיע אל הנפש כי הם יחייבוהו לצאת משם, והמשלתי הדבר למלך שהיו שועריו גנבים ולסטים והבאים לקבול לפני המלך מהם היתכן שהשוערים ההם יוציאו להם רשות ליכנם לחייבם למלך, כמו כן הדבר הזה, והוא אומרו **כי יהיה לאיש** וגו' **איננו שומע** וגו' פירוש מושלל הוא בערך השמיעה כי לא יגיעוהו הדברים מצד המונע היושב על מפתחי הלב כאומרם ז''ל (ברכות ס''א.):
@9 **בקול אביו ובקול אמו**. טעם שהוצרך להזכיר אביו ולא הספיק לומר בקולו וחוזר לאביו שאמר שאמר בסמוך, העיר הכתוב כי בן סורר ומורה ליולדיו יסובבהו כן היותו מורד באביו ואמו שהם הקב''ה וכנסת ישראל (זוהר ח''ב פ''ה), על דרך אומרו (משלי א') שמע בני מוסר אביך ואל תטוש תורת אמך, כי לפי שיולדיו חושכים שבטם מבניהם ומניחים אותם לעשות הטוב והישר בעיניהם, זה יסובב שגם בהם ימרוד, וזה שיעור הכתוב **כי יהיה לאיש** וגו' דע שאיננו שומע בקול הקב''ה וכנסת ישראל ולזה הגם שיסרוהו לא ישמע אליהם פירוש מלבד שלא יקבל לחזור מעבירות שבינו ובין המקום עוד לו שלא ישמע אליהם:
@13 **וכי יהיה באיש חטא וגו'**. סמך פרשה זו לשלפניה, לפי שהיה מסלסל סדר תיקון האדם, בתחילה העירו על עצמו כמו שפירשתי ברמז פרשת כי תצא, אחר כך העיר האב על הבן כמו שרמזנו בפסוק כי יהיה בן סורר וגו', וכאן העיר על חכמי הדור לפקוח עין על עושי עול, והוא אומרו **כי יהיה באיש חטא משפט מות** ונשאר עומד במרדו ולא חזר בתשובה עד שמת בחטאו, והוא אומרו **והומת**, ותלה ה' חסרונו על החכם כאומרו **ותלית אותו על עץ** זה החכם עץ עושה פרי שהוא יטול עונשו, כי ה' ציוהו להוכיח ולחזור ולהוכיח עד הכאה (ערכין ט''ז:) וכמו שכתבנו בפרשת קדושים, וכשהוא העלים עינו מאיש זה עד שמת מתחייב בו:
@13 **ואומרו לא תלין וגו'**. בא לצוות להמון עם שלא יהרהרו אחר החכם, על דרך אומרם (תנדב''א פ''ג) אם ראית תלמיד חכם שעבר עבירה ביום אל תהרהר אחריו בלילה שמא עשה תשובה והעמידוה בודאי עשה תשובה, והוא אומרו **לא תלין נבלתו** כי החטא יקרא גם כן נבילה לא תהרהר אחריו בלילה שהוא זמן לינה אחת על העץ שהוא תלמיד חכם, **כי קבור תקברנו** לאותו חטא מעל העץ ביום ההוא עצמו, והטעם **כי קללת אלהים** שאם אינך עושה כן אתה מחלל שם שמים וכאלו אתה נוגע בכבודו יתברך:
@13 **וגמר** אומר **ולא תטמא** את אדמתך, יתבאר על דרך אומר' ז''ל (שבת קי''ט:) לא חרבה ירושלים אלא על שהיו מבזים בה תלמוד חכמים שנאמר (דה''ב ל''ו ט''ז) ויהיו מלעיבים וגו', ולזה צוה ה' שלא יסובבו בביזוי תלמיד חכם טומאת הארץ בביאת גוים בנחלת ה' ויטמאוה:
@15 **לא תראה את שור וגו'**. פרשת זו באה לרמוז בפרטות חיוב התוכחות שצריכין בני אל חי צדיקי עולם לעשות לעם ה', והן אלה צדיקים יקראו לצד מעלתם אחים, כמו שהעירותיך שכינוי זה הוא מדריגה היותר מעולה שבכל כינויים אשר יתכנו בהם יחידי עם, (שמות רבה נ''ב) ואותם צוה ה' כי תראה את שור אלה הם בני אדם שנמשלו כבהמות והם צאן קדשים ולזה קראם שור ושה, **אחיך** שהוא הקב''ה, ויחם לו שם זה להעיר אל מי מקדושיו הוא מצוה שהם הצדיקים כמו שכתבנו:
@15 **ואומרו נדחים** על דרך אומרו (לעיל ד') ונדחת והשתחוית להם וגו' שהעובר פי ה' יקרא נדח, ויצו ה' לבל יתעלם אלא ישיבם לאחיו הוא אלהי עולם וכפל לומר השב תשיבם, נתכוון כי מתחילה ישיבם לדרך הטוב ובזה יתקרבו אל אביהם שבשמים, והוא אומרו תשיבם לאחיך:
@15 **ואומרו ואם לא קרוב אחיך וגו'**. בזה העיר כי הוא מדבר על זמן גלות האחרון כי לא קרוב כדרך אומרו (במדבר כ''ד) אשורנו ולא קרוב, עוד לו ולא ידעתו שנסתם הקץ ואין יודע מתי קץ הפלאות, וזה יסובב הרחקת הלבבות מהאמונה ונטויי רגל כאשר עינינו רואות בדורות הללו, עם כל זה יצו ה' **ואספתו אל תוך ביתך** זה בית המדרש וילמדהו אורחות חיים ודרך ישכון אור לבל יטה מני אורח ולא ימצאהו אויבו במחשבות וטענות כוזבות כי אור תורה תצילהו, וזה יהיה עד שיתרצה ה' וידרשהו, והוא אומרו **עד דרוש אחיך אותו**, **והשבותו לו** פירוש מעלה עליו הכתוב כאילו הוא משיבו מני אובד:
@15 **או** ירצה שצריך החכם להשתדל עם בני ישראל בכח התורה והמוסר עד יום פקודה שידרוש ה' נשמתו ואז הרוח תשוב אל האלהים, ודקדק לומר **והשבותו לו** שאם ימעדו קרסוליו לא תשוב הנפש אל האלהים ותלך לחרפות:
@17 **ואומרו וכן תעשה**. לפי שיש באמצעות האדם ג' דברים, הא' הרכבת הגוף, ב' חלק הרוחני שבאדם ג' חלק התורה המאורסת לכל א' מישראל, כנגד הרכבת הגוף אמר **כן תעשה לחמורו**, כנגד חלק הרוחני אמר **כן תעשה לשמלתו** כי בחינה זו תקרא שמלה כאומרם במם' שבת (קנ''ב:) משל למלך שחלק בגדי מלכות, וכנגד חלק התורה אמר **וכן תעשה לכל אבדת אחיך**, וקראה הכתוב אבדה כמו שרמז רשב''י (קידושין ב':) משל למי שנאבדה לו אבדה מי מחזר על מי וכו', כי חלק העולה לאיש זה הנה הוא אבוד מהעולם כיון שאין זולתו יכול להשיגו כאמור בדברי המקובלים, ובאמצעות השבתו בתשובה הנה הוא מוצא אותה:
@18 **ואמר** עוד **לא תראה חמור אחיך וגו'**. נתכוין בזה שלא יאמר הצדיק שלא נצטוה אלא על איש שנידח בעבירות אבל ישנו בהשב אבל אם נפל והרבה להרשיע הלנופלים תקומה ואבדה תקוה ממנו, לא כן הוא אלא לא תראהו ותתעלם וצריך להקים עמו, דקדק לומר **עמו** דוקא אם הוא מסייע בדבר שרוצה לשוב, אבל אם הוא נופל ואינו חפץ בהקמתך פטור אתה שזה נכנס בגדר לץ וכתיב (משלי ט') אל תוכח לץ פן ישנאך:
@27 (יג~כ) **כי יקח איש אשה וגו'**. דברה תורה כנגד בני אדם גם בני איש אשר חוזרים פניהם מן התורה כאומרם כי היום קצר למה שצריך להשתדל על המחיה, ועליהם אמר הכתוב **כי יקח איש אשה** זאת התורה המאורסה, **ובא אליה** שכבר זרחה עליהם אורה של תורה בהר סיני וקבלו הלוחות, **ושנאה** פירוש שאין לבם חפץ לתת לה עונתה במשפט, וכשבא מוכיח לדבר אליו למה תמאם אשת נעורים משיב כי אין התורה זנה ומפרנסת והוא צריך למחיה, גם אינו רואה סימן ברכה מאמצעות לימודה הגם כי יעסוק בה אין נפתחין לו שערי פרנסה טובה, ואדרבא רואה כי כל האנשים שרחקוה ואינם חושבים בה כל עיקר בתיהם מלאים כל טוב, והוא אומרו **ושם לה עלילות דברים**, והוציא עליה שם רע באומרו **את האשה הזאת לקחתי** פירוש שאינו כופר בליקוחיה, אלא שאומר ואקרב אליה ולא מצאתי לה בתולים פירוש לשון חוזק כי עוסקיה סביב יחנו לדפוק על דלתי אחרים למצוא טרף, מודיע הכתוב כי הקב''ה שהוא הנקרא אבי הנערה וכנסת ישראל יתבעו עלבונה של תורה לפני בית דין הגדול, והוא אומרו **ולקח אבי הנערה ואמה**, והוציאו את בתולי הנערה רמז חוזק ועליה והשגות רמות יושגו באמצעותה ויתבעו עלבונה בב''ד כאומרו השערה, והוא מה שאמרו בזוהר (ח''ג פ') כי עתיד הקב''ה לתבוע עלבונה של תורה, וכאומרם במשנה (אכות פ''ו) אוי להם לבריות מעלבונה של תורה:
@27 **והנה** טענת העומד לתבוע עלבונה כתובה לפנינו כאומרו **ואמר אבי הנערה אל הזקנים את בתי נתתי לאיש הזה לאשה** פירוש לא נתתיה לעגנה בקרן זויות אלא להתנהג עמה במנהג אשה לבל יגרע שארה כסותה ועונתה, כמו שמפורשים שלשת הדברים בס' הזוהר (תיקונים ו') שכולם צריכין לתורה, **וישנאה** כאן רמז סיבת ההרחקה ממנה שבאה מאותה בחינה הנקראת שנאה, ונותן טעם ההרחקה מפני שלא מצא בה תוקף וחוזק, והוא אומר **והנה הוא שם עלילות** וגו', דקדק לומר והנה הוא להעיר כי אין זה אמת שלא גרם לו אלא השונא השוכן בקרבו, **ואלה בתולי בתי** וגו' והיו הדברים ברורים כשמלה כמה מעלות וחוזק התורה, שתחילת כל דבר כל העולם כלו בה נברא, בשבילה נברא, ובה מתקיים, וכל טובה הצפונה לעולם הבא ואוצרות החיים והטוב נקנית בה:
@27 **ואמר** הכתוב כי זה יהיה משפט האיש ההוא על פי בית דין, ראשונה ויסרו אותו על דרך אומרם ז''ל (ברכות ה'.) אם רואה אדם שיסורין באים עליו וכו' יתלה בביטול תורה פירוש על מה שבטל התורה, ונדחקו האחרונים בפירוש דבר זה בטענת הלא ביטול עון גדול הוא ולמה לא תלה בו עד שלא מצא, ויישוב הדבר הוא לפי שאין שיעור למה שצריך בעסק התורה כאומרם (אבות פ''ב) ואין אתה בן חורין להבטל ממנה, והגם שיראה בעיני אדם שעסק, כשיראה יסורין באים עליו באין עון ידע כי כמו שראוי לו לעשות לא עשה ועל זה ענשוהו:
@27 **ואומרו וענשו אותו מאה כסף**, רמז למאה ברכות שחייב לברך בכל יום, כמו שדרשו (מנחות מ''ג:) מאומרו ועתה ישראל מה ה' אלהיך שואל אל תקרי מה אלא מאה ופסוק זה בבעל תשובה נאמר כאומרם בגמ' (ב''ר פכ''א) ועתה אין ועתה אלא תשובה דכתיב ועתה ישראל מה ה' אלהיך שואל וגו' ע''כ, שחייב להשתדל להשלימם:
@27 **ואומרו ונתנו לאבי הנערה**, שכולן הם ברכות לה' שהוא אבי הנערה, ואומרו **כי הוציא שם רע על בתולת ישראל** שהיא השכינה שהיא כללות ישראל והיא מדה העשירית שכוללת מאה והיא נקראת תורה שבעל פה כידוע ליודעי חן, ואומרו **ולו תהיה** וגו' פירוש הגם שאין חיוב בתלמוד תורה אלא קביעות עתים אדם כזה שהוציא שם רע עליה צריך לשקוד על דלתותיה כל היום וכל הלילה לא יוכל לשלחה כל ימיו, וכזה מצינו להם לרבותינו ז''ל (ויק''ר פכ''ה) שאמרו שבעל תשובה אם היה רגיל ללמוד דף אחד ילמוד שנים וכן על זה הדרך, וזה בעל תשובה משאר העבירות אבל מוציא שם רע על התורה משפטו כל ימיו עמה ישב תורתו אומנתו:
@27 **ואומרו ואם אמת היה הדבר** וגו', פירוש אם אירע כי תורה שלמד זה האיש ובחן בה שאין לה בתולים, שהיתה תורת מינות שלמדו צדוק ובייתוס ותורה כזו אין בה חוזק והיא חלק רע, לתורה כזו יצו ה' לרמות בה אבן לסוקלה ולאבדה כאומרו ומתה, הגם כי הן הנה הדברים שיצאו מפי הקב''ה אף על פי כן הכונה לא כן הוא, וכבר אמרו ז''ל (גיטין מ''ה:) על ספר תורה שכתבו מין ישרף, כי עשתה נבלה לזנות וגו' ובערת הרע כי זו תקרא חלק רע וצריך ביעור:
@27 **ואומרו** עוד **כי ימצא איש שוכב** וגו' יתבאר על פי דבריהם ז''ל (סנהדרין נ''ט.) שאמרו גוי העוסק בתורה חייב מיתה ע''כ, והוא אומרו **כי ימצא איש שוכב עם אשה** שהיא מאורסת לבעלה שהיא התורה כלת ישראל, **ומתו גם שניהם** פירוש העכו''ם העוסק וגם התורה ההיא לא יהיה לה עליה אלא תדעך נרה ואין לה חיות כדרך אמרי תורה דכתיב (משלי ד') כי חיים הם:
@47 **לא יבא עמוני וגו' על דבר וגו'**. קשה אומרו **אשר לא קדמו** והלא מצינו שאמר הכתוב (לעיל ב' כ''ט) כאשר עשו לי בני עשו וגו' והמואבים, ופירשו רבותינו ז''ל (רש''י שם) שחוזר למאמר אוכל בכסף, ב' אחר שהם שכרו עליהם בלעם לקללם מה מקום לחוש על שלא קדמו בלחם, ואולי שאמר **על דבר** וגו' להעיר שעל סיבה זו בלבד יתחייב הדין להרחיקם שלא יבואו בקהל, ופי' קדמו היא להוציא דורון לסעד לבם בלחם וכו' שהם חייבים לעשות כן מכל האומות כעל כל הגמולות אשר גמלם אברהם אבינו עליו השלום, כי מה שמכרו להם לחם ומים היה להנאתם של מואב גם לפתותם להפילם בעריות, והוא מה שדקדק הכתוב לומר **לא קדמו אתכם** פירוש להנאתכם:
@47 **עוד** יתבארו הכתובים על פי דבריהם ז''ל ביבמות דף ע''ו שאמרו מנא הני מילי שמואבית מותרת אמר רבי יוחנן וכו' דקאמר קרא וגו' אמר ליה אבנר תנינא מואבי ולא מואבית אמר לו דואג אלא מעתה ממזר וכו' מצרי ולא מצרית שאני הכא דמפרש טעמא על דבר וגו' דרכו של איש וכו' ואין דרכה וכו' היה להם לקדם וכו' ונשים לקראת נשים בעו לאכרוזי עליה מיד ועמשא וגו' מלמד שחגר חרבו וכו' ואמר כל מי שאינו שומע הלכה זו ידקר בחרב מקובלני מפי בית דינו של שמואל מואבי ולא מואבית, מכל מקום קשיא תרגמא כל כבודה בת מלך פנימה, כתנאי עמוני ולא עמונית מואבי ולא מואבית דברי רבי יהודה רבי שמעון אומר על דבר אשר לא וגו' דרכו של איש לקדם וכו' עכ''ל, וכתבו התוספות בד''ה כתנאי וזה לשונם ואם תאמר לר' יהודה תקשי ליה מצרי, ואומר ר''י דגבי עמוני ומואבי היה לו לקצר ולכתוב עמון ומואב הלכך אית לן למדרש דלמעט עמונית ומואבית אבל מצרי אם היה כותב מצרים היה מאריך, והאי דכתב אדומי ולא כתב אדום אגב מצרי כתב אדומי עכ''ל:
@47 **ואין** דברי התוספות נראים כי לא מצינו שיאמר הכתוב לשון בתחילה אגב מה שעתיד לומר אחריו ומה גם במקום שיש לטעות בהלכות, ועוד בשלמא אם חלוקת מצרי עצמה היה צריך הכתוב לכתוב מצרי יש מקום לומר ששינה הכתוב בשלפניה לדבר כיוצא בה, ואם מצרי עצמה לא דיבר הכתוב כהוגן שהיה צריך לכתוב מצרים לכלול מצרית אלא שאנו אומרים שלא רצה להאריך איך נאמר שאמר אדומי אגב מצרי שמצרי גופה עליה אני דן:
@47 **ולבא** לעומק הדבר יש להעיר בדברי אבנר למה אחז החבל בב' ראשין מתחלה אמר דיוק מואבי כסברת רבי יהודה וחזר לתת טעם על דבר אשר לא קדמו וגו' כסברת ר' שמעון כי ממשמעות הלשון מוכח שכשאמר טעם שני לא חזר בו מטעם הראשון, והסברא נותנת כן שאם לא כן למה אמר אבנר טעם שסתירתו בצדו, בשלמא לר''י לדברי התוספות הגם שהקשינו עליהם לסברתם מיהא אמר דבריו מטעם שאמרו, אלא אבנר הרי גילה דעתו במה שחזר מקושית מצרי שאינו סובר לחלק כמו שחלקו התוספות:
@47 **אכן** נראה כי כונת אבנר לסברת ר' יוחנן היא שדורש מאומרו מואבי ומאומרו על דבר אשר וגו', שזולת על דבר יש לסתור הדרשה ממצרי, וטעם על דבר אשר וגו' לבד אם היה אומר מואב ועמון הגם שאומר על דבר וגו' היינו אומרים הגם שהטעם אינו צודק אלא באנשים באה הגזירה על כולו כאחת, ועוד שהנשים באים גם כן מזרע פסול שהם הזכרים שאסורין ובכיוצא בזה אין אנו הולכים אלא אחר האב דכתיב למשפחותם לבית אבותם, ואם אמר עמוני ומואבי ולא היה לנו טעם על דבר היינו אומרים שאמר מואבי כמו שאמר מצרי ואדומי, ומשניהם דורש ולא עמונית ולא מואבית:
@47 **ולזה** אמר אבנר ב' טעמים הנזכרים, ומחלוקת רבי יהודה ור''ש היא על זה הדרך, כי ר''י סובר דטעם מואבי לבד יתחייב לומר ולא מואבית, ומאמר על דבר אינו מחייבני לא לרבות ולא למעט כאשר אבאר הטעם, וטעם מצרי ואדומי משום שהטעם שנתן הכתוב מחייבני לכלול גם מצרית ואדומית שכ''כ הם אחים האנשים כנשים, גם גרות הארץ שהיינו בה שוים בה אנשים ונשים, ולא חש הכתוב לומר מצרי ואדומי כיון שאין מקום לטעות כנזכר, ולא סבר כר' שמעון להוכיח מאומרו על דבר או מטעם שכתבנו בפירוש דברי אבנר או מטעם שיש לחוש לדחייתו של דואג:
@47 **ומה** שתרגמה בגמ' כל כבודה יש לצדד ולומר אפשר שלא אמר כל כבודה בת מלך פנימה אלא דוקא בכבודה לא בזונה אחר שאנו רואין מעשיה מעשה חצופות גלה כבוד מהם וחזר הדין לומר היה להם לקדם וכו' ונשים לנשים, ויש פנים לומר שאין להביא ראיה מהפקרתם לזנות מב' טעמים, א' אנוסים היו מצד שהפקירום האנשים, ב' התורה לא תקפיד עליהם למה לא עשו דבר שאין דרך ארץ לנשים לעשותו משום כל כבודה הגם שהם זלזלו בעצמן בדבר אחר, ומעתה הדברים שקולים ואין הוכחה מעל דבר והוכיח מדקדוק עמוני ומואבי:
@47 **ור'** שמעון סובר בהכרעה כי לעולם ישנם בטענת כל כבודה ופטורים מהקדמת הלחם ודרשינן טעם הכתוב, ולדרך זה יתבאר אומרם בגמרא כתנאי שחוזר על מאמר כל כבודה בת מלך פנימה ולזה סמכה לה, כי לפי פירושינו כל עיקר מחלקותם של ר' יהודה ור' שמעון אינה אלא אם יאמר עליהם טענת כל כבודה או לא:
@47 **נמצאת** אומר ג' סברות באגדה זו, לפי שמועת ר' יוחנן דורש מאומרו מואבי ומאומרו על דבר, ולסברת ר' יהודה מאומרו עמוני לבד, ולסברת ר' שמעון עיקר הדרשה הוא מאומ' על דבר:
@47 **ומעתה** בשלמא לדברי ר' שמעון גם לשמועתו של ר' יוחנן יש טעם נכון למאמר **על דבר**, אלא לסברת רבי יהודה שאינו דורש אלא מתיבת עמוני ומואבי קושייתנו במקומה עומדת למה הוצרך לומר הכתוב **על דבר**, ויתישב כמו שכתבנו בתחילת הענין:
@47 **שוב** עמדתי אל תוכן ענין זה וראיתי שאין טענה על הנקבות לקדם לנשים כי הגע עצמך שירצו בלבם לקדם היכול ילכו עשות בלא רשות בעליהן ומה גם בראות בעליהן אויבים להם אנוסים הם הגם שלא יקדמו אותם, ומעתה אין טענת אשר לא קדמו אלא על הזכרים ועמד הדין עמוני ולא עמונית מואבי ולא מואבית וטענת דואג טענת מין, וכמו שאמר אחיה השילוני כשאמרו לפניו קושיא זו הפירה ואמר מינאה כאמור במדרש (מדרש שמואל כ''ב):
@49 **ולא אבה וגו'**. אומרו **ולא אבה** פירוש הגם שהיה מקום לשמוע מצד ענפי החטא שהיה בלעם נאחז בהם, אף על פי כן נתרצה ה' בלא טעם ולא שמע וגו', ונתן הטעם כי אהבך ה' פירוש לא לצד שהיית ראוי לדבר זה, ועיין מה שפירשתי בפסוק ולא אבה סיחון (לעיל ב' ל'):
@53 **כי תצא מחנה וגו'**. פירוש הגם שיש דקדוקי עבירות שה' לא יעניש עליהם ואם יעניש יהיה עונש קל, מודיע הכתוב שבשעת הסכנה שהוא בזמן שיוצאים על אויביהם צריכין שמירה מכל דקדוקי עבירות כאומרו **מכל דבר רע** וגו', וכלל בתיבת **דבר** גם סיבות שממנו יסובב הרע, והעיר במה שצוה סמוך לזה כי יהיה בך איש אשר לא יהיה טהור וגו' ואמרו רבותינו ז''ל (כתובות מ''ו.) שהרהורי עבירה ביום מביאין לידי קרי בלילה, ונתכוין הכתוב בסמיכות זה לומר שעל כיוצא בזה יצו במאמר ונשמרת מכל וגו':
@64 **לנכרי תשיך ולאחיך לא תשיך**. קשה למה כפל לומר **ולאחיך לא תשיך** אחר שצוה בסמוך לא תשיך לאחיך וגו', ורבותינו ז''ל אמרו (ב''מ ע''ה:) לעבור עליו בב' לאוין, ואולי שנתכוין לומר שהגם שהנשיכה היא לגוי אם הדבר על ידי ישראל אסור כל עוד שישראל אינו מכיר הגוי בעד הלואתו או אם אין בידו משכון הגוי וכך הוא הדין:
@64 **עוד** ירמוז למה שחלקו האחרונים (יו''ד סי' קנ''ט) שאפילו לגוי אסור להתמיד בזה משום שמא יבא ליתנו גם לישראל, והוא אומרו **לנכרי תשיך** ותנאי הוא הדבר שלא תעשה באופן שיצא מזה קלקול שתשיך לאחיך:
@65 **והיה בך חטא וגו'**. פירוש על דרך אומרם ז''ל (שבת ל''ב:) בעון נדרים מתים אשתו ובניו של אדם ע''כ, והוא אומרו **והיה בך חטא** לשון חסרון שעל ידי איחור הנדר יחסר ממנו אשתו שהיא כגופו או זרעו שהוא גם כן חלק ממנו, ואומרו **וכי תחדל לנדור לא יהיה בך חטא**, יתבאר גם כן על דרך אומרם ז''ל (גיטין ז'.) אם רואה אדם שנכסיו מצומצמים יעשה מהם צדקה, ועוד אמרו (כתובות ס''ו:) מלח ממון חסר, והנה לפי שחביב על האדם ממונו אין נוח להוציאו ולזה תבא הסברא לאדם להתחכם לנדור נדר לה' שבזה יהיה לו נוח הרצון לתת מנכסיו, לזה בא דבר מלך והודיעו היוצא מחשש ביטול הנדר, והיוצא מחשש מניעת נתינת צדקה כפי המתחייב:
@65 **ואמר** כנגד איחור הנדר שזה יסובב שיהיה החסרון בו, וכנגד מניעת נתינת צדקה אמר וכי תחדל לנדור הגם שאתה בא לידי מניעת נתינה הצדקה זה יסובב חסרון בממון אבל בך בודאי שלא יהיה חטא, והוא אומרו לא יהיה בך חטא:
@67 **ואומרו מוצא שפתיך תשמור וגו'**, פירוש תמתין מלהוציא הנדר מפיך עד שתוכל לעשות פירוש לקיים הנדר אז תדור ותקיים הנדר, סמוך לנדרך, והוא אומרו **ועשית כאשר נדרת**, וכן היה הלל עושה שהיה מביא קרבנו לעזרה ואמר (פסחים ס''ו:) וכו', או שיעור הכתוב הוא על זה הדרך **מוצא שפתיך תשמור** מלדבר, ותעשה כאלו נדרת לה' אלהיך הגם שאינו אלא נדבה, והוא אומרו **כאשר נדרת נדבה** אשר נדבה רוחך, כי משמעות נדבה היא בלב כאומרו (שמות כ''ה ב') אשר ידבנו לבו, נדבה רוחו (שם ל''ה כ''א):
@67 **ואומרו אשר דברת בפיך** יתבאר על דרך אומרם בזוהר (ח''ג רצ''ד.) בפסוק (קהלת י' כ') כי עוף השמים יוליך את הקול כי כשאדם חושב בדעתו מחשבה שפתותיו דובבות מעצמן בלא ידיעתו, והוא אומרו **אשר דברת בפיך** כי הגם שלא עשה אלא מחשבה פיך דיבר מה שחשב, ולזה דקדק לומר **בפיך** שאם לא כן למה הוצרך לומר בפיך וכי אין אנו יודעים כי הדיבור הוא בפה, ולדברינו יבא על נכון, ורבותינו ז''ל (ר''ה ו'.) דרשו הכתוב באופן אחר, וע' פנים לתורה:
@68 **ואל כליך לא תתן**. אומרו **ואל כליך** בתוספת וא''ו להעיר, שקדמה מצוה אחרת והוא שלא יאכל אכילה גסה, והוא מה שדייק באומרו **שבעך** ודרשו ז''ל (ב''מ פ''ז:) לא אכילה גסה והוסיף עוד לומר ואל כליך לא תתן:
@77 **השמר בנגע וגו' זכור וגו'**. לדבריהם ז''ל (שבת קל''ב:) שאמרו שבא להזהיר לבל יקוץ בהרתו, נתכוין בהסמכת **זכור את אשר עשה ה' למרים** להודיע שורש שממנו יהיה הנגע ואותו יצו ה' לקוץ ורפא. (טו) **ואליו הוא נושא וגו' והיה בך חטא**. הכונה שהגם שעושק שכר שכיר אינו אלא גוזל ממון אף על פי כן אין עונשו ממון אלא נפשות, והוא אומרו יהיה **בך** פי' בך בנפשך חטא על דרך (מ''א א') והייתי אני ובני שלמה חטאים, והקדים טעם העונש באומרו ואליו הוא נושא את נפשו ומעתה יהיה המשפט נפש תחת נפש:
@86 **לא תטה משפט גר וגו'**. פירוש שמא תאמר כיון שציוני ה' על הגר אטה דינו לזכותו ת''ל לא תטה וגו', וגמר אומר **ולא תחבול בגד אלמנה** פירוש רק בדבר הזה אני מצוך להטות לזכות שלא תחבול בגד של אלמנה שלא בשעת הלואה הגם שכל חוץ ממנה יחבול בגדיהם:
@93 **אם בן הכות וגו'**. אמר **בן** בחירק רמז שצריך להתבונן בו לדעת אם יכול לסבול המ', אבל אם אמדוהו לפחות מכן אינו לוקה אלא לפי מה שאמדוהו (מכות כ''ב:):
@96 **לא תהיה אשת המת וגו'**. אזהרה לה ולבאיה וחייבת מלקות היא והבא עליה, ואומרו **יבמה יבא עליה** רמז שאין חיוב על היבם אלא ביאה אחת, וכמאמר ר' יוסי (שבת קי''ח:) ה' בעילות בעלתי וחמש נטיעות נטעתי, ואמרו בירושלמי (יבמות פ''א ה''א) שנפלו לו ה' יבמות מה' אחים ונזקק פעם אחת לכל אחת, ואומרו **ולקחה** שלא תאמר שאוסרה עליו מכאן ואילך תלמוד לומר ולקחה לו לאשה שהרשות בידו אם ירצה לקיימה עולמית, ואומרו **ויבמה** שלא תאמר שלא נאמרו כל הדברים האמורים אלא רשות לפי שאסרה הכתוב לעולם התירה ליבם אבל התורה לא חייבתו בדבר, תלמוד לומר ויבמה:
@100 **וענתה וגו'**. אמר לשון עניה, פירוש תשובה לדברי היבם שאמר לא חפצתי לקחתה תענה היא ותאמר ככה יעשה לאיש וגו':
@102 **להציל וגו' ושלחה ידה וגו'**. ולא אמר הכתוב ושלחה ידה וגו' להציל את אישה, העיר בזה שאם לא היה לה מציאות להציל בעלה מיד מכהו אלא על ידי זה לפי שאין כח בה להציל אלא בדרך זה פטורה, ודוקא שהיה חברו מכהו מכת נפש, לזה הקדים מאמר להציל קודם מאמר ושלחה לומר שאם ידענו שלא שלחה אלא להציל פטורה:
@107 **כל עושה אלה כל עושה עול**. פירוש כל עושה אלה אבן ואבן איפה ואיפה, כל עושה עול הדומה לאלה, שלא תאמר שגזירת הכתוב הוא על ב' דברים אלו ולא על דומיהם תלמוד לומר כל וגו':
@108 **זכור וגו'**. שאין כיוצא בהם שיצא על ישראל בלא קדימות ידיעתם ממנו אלא כאשר ידאה הנשר והוא קרך בדרך:
@109 **אשר קרך**. יתבאר על פי דבריהם ז''ל (ד''ה ג'.) שאמרו שהענן היה מכסה על ישראל ולא היה מקומם ידוע לעולם אלא כשמת אהרן נסתלקו ענני כבוד ובא הכנעני וילחם עם ישראל, ואם כן תקשה מנין ידע עמלק מקום חניית ישראל לבא אצלם להלחם עמם, לזה אמר **אשר קרך** פירוש יקר מקרהו וידע מחניהם בדרך, ואומרו **ויזנב בך** וגו' פירוש לא שהענן הניחו ליכנם לפנים למחנה ישראל אלא באותן שהיה הענן פולטן, והוא אומרו ויזנב בך אותם הנחשלים אחריך:
@109 **ואתה עיף ויגע וגו'**. עיף עדיין משעבוד מצרים ויגע מטורח הדרך, ואומרו **ולא ירא אלהים** פירוש ובזה בא המורך בלבבך יותר ממפעל עייפות ויגיעות על דרך אומרו (ישעי' ל''ג) פחדו בציון חטאים, אבל אם היו צדיקים לא יפחדו ולא ירהו במלחמתו, והעיר הכתוב בטעמים שמשניאים אותו בלבנו כי הצר לישראל צרה גדולה שבא עליהם כאשר ידאה הנשר בלא ידיעה כמו שרמז גם כן במאמר קרך והם יגעים ועייפים ודבר המעמיד הכח ביכולת הנעלם אין עמם מה שלא היה כן בשאר כל המלחמות שמלבד שלא ייעפו ולא ייגעו במלחמות עוד להם כלם צדיקים יראי אלהים נמוכי לב:
@109 **חסלת פרשת כי תצא**
